args.content:
SELECT ?item ?itemLabel ?coords
WHERE {
  ?item wdt:P31/wdt:P279* wd:Q1656687 ;  # instance of (or subclass of) point of interest
        wdt:P625 ?coords.

  # Constrain to Alicante (Q8813) or Spain (Q29)
  FILTER(
    ?item wdt:P131* wd:Q8813 ||  # located in Alicante or sublocation
    ?item wdt:P17 wd:Q29         # or located in Spain
  )

  SERVICE wikibase:label {
    bd:serviceParam wikibase:language "en,es".
  }
}
LIMIT 100

